def extract_and_paint(g):
 g=[row[:] for row in g]; R,C=len(g),len(g[0]); color=next(v for row in g for v in row if v not in (0,2,8))
 # connected special components, first
 pts={(r,c) for r in range(R) for c in range(C) if g[r][c]==color}
 start=min(pts); comp={start}; q=deque([start])
 while q:
  r,c=q.popleft()
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   p=(r+dr,c+dc)
   if p in pts and p not in comp: comp.add(p);q.append(p)
 minr=min(r for r,c in comp);minc=min(c for r,c in comp)
 mask={(r-minr,c-minc) for r,c in comp}; mh=max(r for r,c in mask)+1;mw=max(c for r,c in mask)+1
 out=[row[:] for row in g]
 for r0 in range(R-mh+1):
  for c0 in range(C-mw+1):
   cells=[(r0+dr,c0+dc) for dr,dc in mask]
   if all(g[r][c]==0 or g[r][c]==color for r,c in cells):
    for r,c in cells: out[r][c]=color
 return out,mask
